import json,sys
try:
    d = json.load(sys.stdin)
    def redact(o):
        if isinstance(o, dict):
            return {k: redact(v) for k,v in o.items()}
        if isinstance(o, str) and len(o) > 12:
            return o[:6] + '...[REDACTED]...' + o[-4:]
        return o
    print(json.dumps(redact(d), indent=2))
except Exception as e:
    print('parse error or empty:', e)
"
